package com.cenedu.backend.ai.problem.render; import com.cenedu.backend.domain.problem.authoring.diagram.*; public final class CoordinateGraphSvgRenderer { public String render(CoordinateGraphDiagramSpecV1 s){int p=s.viewport().padding();return "<line x1=\""+p+"\" y1=\""+(s.viewport().height()/2)+"\" x2=\""+(s.viewport().width()-p)+"\" y2=\""+(s.viewport().height()/2)+"\" stroke=\"#000000\"/><line x1=\""+(s.viewport().width()/2)+"\" y1=\""+p+"\" x2=\""+(s.viewport().width()/2)+"\" y2=\""+(s.viewport().height()-p)+"\" stroke=\"#000000\"/>";} }
